import{_ as t,o as a,c as s,a3 as n}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Archive Layout","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Archive Layout | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/layout"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/layout"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/layout"}]]},"headers":[],"relativePath":"xclang/reference/layout.md","filePath":"en/xclang/reference/layout.md","lastUpdated":1791301679000}'),o={name:"xclang/reference/layout.md"};function d(c,e,i,l,r,h){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="archive-layout" tabindex="-1">Archive Layout <a class="header-anchor" href="#archive-layout" aria-label="Permalink to &quot;Archive Layout&quot;">​</a></h1><p>What an unpacked toolchain archive holds: the toolchain directory, <code>$XCLANG</code> in these docs. Every host archive holds every sysroot; the archives differ only in the programs of <code>bin/</code>. Why it is laid out this way is in <a href="./../design/toolchain">toolchain structure</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang/</span></span>
<span class="line"><span>  bin/                     llvm and its names (clang, clang++, clang-cl,</span></span>
<span class="line"><span>                           clang-scan-deps, ld.lld, ld64.lld, lld-link,</span></span>
<span class="line"><span>                           llvm-ar, llvm-objcopy, windres, dsymutil,</span></span>
<span class="line"><span>                           llvm-gsymutil, ...), the tools outside it</span></span>
<span class="line"><span>                           (llvm-profdata, llvm-cov, llvm-dwarfdump,</span></span>
<span class="line"><span>                           llvm-strings, FileCheck), the xclang command,</span></span>
<span class="line"><span>                           and &lt;target&gt;.cfg for every spelling of every</span></span>
<span class="line"><span>                           target</span></span>
<span class="line"><span>  lib/clang/&lt;major&gt;/       clang&#39;s resource headers, compiler-rt&#39;s headers,</span></span>
<span class="line"><span>                           and compiler-rt for every target</span></span>
<span class="line"><span>  lib/cmake/xclang/        the CMake package</span></span>
<span class="line"><span>  libc++/include/c++/v1/   libc++&#39;s headers, the same for every target</span></span>
<span class="line"><span>  libc++/include/&lt;target&gt;/c++/v1/</span></span>
<span class="line"><span>                           each target&#39;s own __config_site, &lt;target&gt; as</span></span>
<span class="line"><span>                           clang spells it (x86_64-w64-windows-gnu)</span></span>
<span class="line"><span>  mingw-w64/include/       mingw-w64&#39;s headers, the same for both Windows</span></span>
<span class="line"><span>                           targets</span></span>
<span class="line"><span>  share/licenses/          the license notices of everything in the archive</span></span>
<span class="line"><span>                           (below)</span></span>
<span class="line"><span>  &lt;target&gt;/                the sysroot of each target (below)</span></span>
<span class="line"><span>  sdk/                     not in the archive: the vendor SDKs that the</span></span>
<span class="line"><span>                           xclang command fetches, and sdk/windows,</span></span>
<span class="line"><span>                           sdk/macos, those in use</span></span></code></pre></div><p>The MSVC targets have no sysroot: their compiler-rt is <code>lib/clang/&lt;major&gt;/lib/windows</code>, their C and C++ libraries are the fetched SDK&#39;s.</p><h2 id="sysroots" tabindex="-1">Sysroots <a class="header-anchor" href="#sysroots" aria-label="Permalink to &quot;Sysroots&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Linux</th><th>Windows (MinGW)</th><th>macOS</th></tr></thead><tbody><tr><td>C library</td><td>glibc 2.17&#39;s headers in <code>usr/include</code>, its startup files and libraries in <code>lib64</code>, <code>usr/lib64</code></td><td>mingw-w64 (UCRT) and winpthreads: the libraries in <code>lib</code>, the headers in the shared <code>mingw-w64/include</code></td><td>none: Apple&#39;s SDK, Xcode&#39;s, or on Linux and Windows hosts <code>sdk/macos</code> (<a href="./../design/macos#the-sdk-on-linux-and-windows-hosts">macOS</a>)</td></tr><tr><td>libc++, libc++abi, libunwind</td><td><code>usr/lib</code>; the headers in the shared <code>libc++/include/c++/v1</code></td><td><code>lib</code>; the same</td><td><code>lib</code> (no libunwind: the system&#39;s, in libSystem); the same</td></tr><tr><td>libc++ module sources</td><td><code>usr/share/libc++/v1</code></td><td><code>share/libc++/v1</code></td><td><code>share/libc++/v1</code></td></tr><tr><td>libc++ module manifest</td><td><code>usr/lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td><td><code>lib/libc++.modules.json</code></td></tr><tr><td>ASan libc++</td><td><code>usr/lib/asan</code></td><td>none</td><td><code>lib/asan</code></td></tr><tr><td>GCC library names</td><td>empty <code>libatomic.a</code>, <code>libgcc.a</code>, <code>libgcc_eh.a</code>, <code>libgcc_s.a</code></td><td>the same, and <code>libssp.a</code>, <code>libssp_nonshared.a</code></td><td>none</td></tr></tbody></table><p><code>clang++ --target=&lt;target&gt; -print-library-module-manifest-path</code> prints the path of the manifest.</p><h2 id="shared-headers" tabindex="-1">Shared Headers <a class="header-anchor" href="#shared-headers" aria-label="Permalink to &quot;Shared Headers&quot;">​</a></h2><p>The headers that are the same for several targets are in the archive once, without links. libc++&#39;s headers differ between the targets only in <code>__config_site</code>, which is each target&#39;s own: <code>libc++/include</code> is LLVM&#39;s per-target runtime layout, <code>c++/v1</code> for all and <code>&lt;target&gt;/c++/v1</code> for each. mingw-w64&#39;s headers are the same for x64 and arm64, in <code>mingw-w64/include</code>. The config files name the directories: <code>-stdlib++-isystem</code> the target&#39;s <code>__config_site</code>, then the shared libc++ headers; for the Windows targets <code>-idirafter mingw-w64/include</code>, which comes after clang&#39;s own headers, as the sysroot&#39;s <code>include</code> would. A build with <code>--no-default-config</code> that sets its own <code>--sysroot</code> names them too.</p><p>They are not in an <code>include/</code> at the top: clang&#39;s drivers look for libc++ in <code>&lt;toolchain&gt;/include/c++/v1</code> by themselves, the macOS one before the SDK&#39;s, so <code>--no-default-config</code> would find xclang&#39;s headers without a <code>__config_site</code> there instead of the system&#39;s. Before 23.1.2.7 each target directory had its own copies, 155 MB of the 800 MB unpacked.</p><h2 id="licenses" tabindex="-1">Licenses <a class="header-anchor" href="#licenses" aria-label="Permalink to &quot;Licenses&quot;">​</a></h2><p>Every archive, the toolchain, libclang, the ASan libclang and the option tables, has <code>share/licenses</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>share/licenses/</span></span>
<span class="line"><span>  README.md                each component: what of the archive it is, its</span></span>
<span class="line"><span>                           version, its license (an SPDX expression) and</span></span>
<span class="line"><span>                           where its source is</span></span>
<span class="line"><span>  sbom.spdx.json           the same as an SPDX 2.3 document</span></span>
<span class="line"><span>  &lt;component&gt;/             the component&#39;s license and notice files</span></span></code></pre></div><p>The toolchain&#39;s components:</p><table tabindex="0"><thead><tr><th>directory</th><th>what</th><th>license</th></tr></thead><tbody><tr><td><code>xclang</code></td><td>xclang&#39;s config files, CMake package and <code>xclang</code> command</td><td>Apache-2.0</td></tr><tr><td><code>llvm-project</code></td><td>clang, lld, the LLVM tools, libc++, libc++abi, libunwind, compiler-rt; the files keep their paths in LLVM&#39;s source</td><td>Apache-2.0 WITH LLVM-exception, and the third-party parts&#39;</td></tr><tr><td><code>zlib</code>, <code>zstd</code></td><td>linked into the programs (macOS hosts: zstd only)</td><td>Zlib; BSD-3-Clause OR GPL-2.0-only</td></tr><tr><td><code>glibc</code></td><td>the Linux targets&#39; C library, 2.17</td><td>LGPL-2.1-or-later</td></tr><tr><td><code>linux</code></td><td>the Linux targets&#39; kernel UAPI headers</td><td>GPL-2.0-only WITH Linux-syscall-note</td></tr><tr><td><code>nss</code></td><td>the Linux targets&#39; <code>libfreebl3.so</code>, which glibc&#39;s <code>libcrypt</code> loads</td><td>MPL-2.0</td></tr><tr><td><code>mingw-w64</code></td><td>the Windows targets&#39; headers, CRT and winpthreads, which the Windows hosts&#39; programs link too</td><td>ZPL-2.1, and the runtime&#39;s other parts</td></tr><tr><td><code>rust</code>, <code>rust-crates/&lt;crate&gt;-&lt;version&gt;</code></td><td>Rust&#39;s standard library and the crates <code>bin/xclang</code> links</td><td>each its own</td></tr></tbody></table><p>glibc, the kernel headers and NSS are those of CentOS 7, as conda-forge&#39;s sysroot packages repackage them: the README names those packages, CentOS&#39;s source RPMs and the upstream releases. The libclang archives carry <code>xclang</code>, <code>llvm-project</code>, <code>zlib</code> and <code>zstd</code> (and <code>mingw-w64</code> on Windows hosts), the option tables <code>xclang</code> and <code>llvm-project</code>.</p><h2 id="without-links" tabindex="-1">Without Links <a class="header-anchor" href="#without-links" aria-label="Permalink to &quot;Without Links&quot;">​</a></h2><p>On Linux and macOS hosts, the tool names in <code>bin/</code> are symbolic links to <code>llvm</code>. The Windows archives hold no symbolic links, so they unpack without extra rights, and conda can package them; every tool name is a small <a href="./../design/windows#the-launchers">launcher</a> instead. The Linux sysroots hold no links either: soname links are the files themselves, and <code>libfoo.so</code> links are linker scripts (<a href="./../design/hermeticity#why-glibc-2-17">why glibc 2.17</a>).</p>`,18)])])}const m=t(o,[["render",d]]);export{g as __pageData,m as default};
